def esc(s): return html.escape(s, quote=True)

def worddiff(old, new):
    a = re.findall(r"\S+|\s+", old); b = re.findall(r"\S+|\s+", new)
    sm = difflib.SequenceMatcher(a=a, b=b, autojunk=False)
    o, n = [], []
    for op, i1, i2, j1, j2 in sm.get_opcodes():
        A = esc("".join(a[i1:i2])); B = esc("".join(b[j1:j2]))
        if op == "equal": o.append(A); n.append(B)
        else:
            if A.strip(): o.append(f"<del>{A}</del>")
            if B.strip(): n.append(f"<ins>{B}</ins>")
    return "".join(o), "".join(n)

